import{_ as a,c as i,o as r,a2 as o}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"1NK","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/1NK.md","filePath":"entries/people/1NK.md"}'),t={name:"entries/people/1NK.md"};function n(s,e,l,c,h,d){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_1nk" tabindex="-1">1NK <a class="header-anchor" href="#_1nk" aria-label="Permalink to &quot;1NK&quot;">​</a></h1><hr><p><strong>OCCUPATION</strong>: Computer security researcher, activist<br><strong>ORGANIZATION</strong>: The Bloc (co-founder, 1999)<br><strong>ACTIVE</strong>: 1999–present<br><strong>STATUS</strong>: Active</p><hr><p><strong>1NK</strong> (also known as <strong>Ink</strong>) is an American computer security researcher and activist. They are best known as a co-founder of <a href="./../organizations/The-Bloc">The Bloc</a>, an organization that investigates alleged corporate misconduct by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a> and related entities.</p><p><strong>At a glance</strong></p><ul><li>Co-founded The Bloc (1999) with <a href="./Z-L1NE">Z*L1NE</a> and <a href="./GUMM1">GUMM1</a></li><li>Co-authored <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999)</li><li>Gained unauthorized access to Miter Corporation secure file systems</li><li>Specializes in network security research and system penetration</li><li>Active in ongoing investigations into <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>1NK is one of three founding members of The Bloc, alongside <a href="./Z-L1NE">Z*L1NE</a> and <a href="./GUMM1">GUMM1</a>. The organization was formed in 1999 following the discovery of classified research materials that 1NK obtained from <a href="./../organizations/Miter-Corporation">Miter Corporation</a> secure servers. According to <em>G</em>BOY Manifesto*, 1NK was potentially the earliest member to uncover evidence of alleged human experimentation programs.</p><p>The Bloc operates as an underground watchdog organization investigating what it claims are illegal research operations involving subjects designated with &quot;G-&quot; prefixes. The group gained prominence following the escape of <a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a> from Saint Juniper Research Campus.</p><h2 id="career-and-activism" tabindex="-1">Career and activism <a class="header-anchor" href="#career-and-activism" aria-label="Permalink to &quot;Career and activism&quot;">​</a></h2><h3 id="early-discoveries" tabindex="-1">Early discoveries <a class="header-anchor" href="#early-discoveries" aria-label="Permalink to &quot;Early discoveries&quot;">​</a></h3><p>1NK gained unauthorized access to Miter Corporation file storage systems in the late 1990s. The materials obtained indicated research programs focused on human cognitive enhancement and what The Bloc characterized as &quot;psychic experimentation.&quot; These findings formed the basis for The Bloc&#39;s founding mission.</p><p>According to The Bloc&#39;s published materials, 1NK discovered that Miter Corporation operated research facilities near <a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a> in Saint Juniper and that these facilities were conducting trials on human subjects.</p><h3 id="formation-of-the-bloc" tabindex="-1">Formation of The Bloc <a class="header-anchor" href="#formation-of-the-bloc" aria-label="Permalink to &quot;Formation of The Bloc&quot;">​</a></h3><p>1NK met <a href="./Z-L1NE">Z*L1NE</a> at the <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a> around 1999, where both were conducting independent research. Along with fellow researcher <a href="./GUMM1">GUMM1</a>, the three formed The Bloc and established operations in basement facilities provided by the <a href="./../locations/St-Juniper-Paranormal-Museum">museum</a>&#39;s proprietor, <a href="./Magdalena">Magdalena</a>.</p><p>The founding members published <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* in 1999, which outlined their analysis of what they termed &quot;coercive homogeny&quot; and &quot;memetic control&quot; allegedly practiced by corporate entities including Miter Corporation. The document positioned The Bloc as resisting centralization and uniformity.</p><h3 id="ongoing-operations" tabindex="-1">Ongoing operations <a class="header-anchor" href="#ongoing-operations" aria-label="Permalink to &quot;Ongoing operations&quot;">​</a></h3><p>1NK continues to participate in The Bloc&#39;s network security research. Recent communications indicate ongoing efforts to penetrate operational messaging systems and secure databases associated with the research campus. 1NK works in coordination with <a href="./Z-L1NE">Z*L1NE</a>, who handles communications security, and <a href="./GUMM1">GUMM1</a>, who conducts data analysis.</p><h2 id="technical-expertise" tabindex="-1">Technical expertise <a class="header-anchor" href="#technical-expertise" aria-label="Permalink to &quot;Technical expertise&quot;">​</a></h2><p>1NK specializes in gaining unauthorized access to secure corporate networks and file systems. Their early penetration of Miter Corporation servers demonstrated capabilities in bypassing institutional security measures. Within The Bloc&#39;s structure, 1NK functions as one of the primary technical researchers responsible for obtaining classified materials.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Z-L1NE">Z*L1NE</a></li><li><a href="./GUMM1">GUMM1</a></li><li><a href="./Magdalena">Magdalena</a></li><li><a href="./Kai-Shepherd">Kai Shepherd</a></li><li><a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a></li><li><a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a></li><li><a href="./../organizations/The-Bloc">The Bloc</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><a href="./../../lore/GBOY-MANIFESTO">G*BOY Manifesto</a> — Founding document co-authored by 1NK, Z-L1N3, and GUMM1 (1999)</li><li>&quot;The Bloc: Saint Juniper&#39;s Paranormal Activists,&quot; coverage of activist organization</li><li>Online communications from The Bloc network (2025)</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',27)])])}const m=a(t,[["render",n]]);export{p as __pageData,m as default};
